package server

import("crypto/subtle";"encoding/json";"log";"net/http";"strings";"time"
"github.com/ABHILASH9519/Corrective-Rag/internal/config"
"github.com/ABHILASH9519/Corrective-Rag/internal/engine")
func New(e *engine.Engine,c config.Config)http.Handler{mux:=http.NewServeMux();mux.HandleFunc("GET /health/live",func(w http.ResponseWriter,r *http.Request){write(w,200,map[string]string{"status":"alive","language":"go"})});mux.HandleFunc("GET /health/ready",func(w http.ResponseWriter,r *http.Request){if c.APIKey==""{write(w,503,map[string]string{"status":"not_ready","missing":"GROQ_API_KEY"});return};write(w,200,map[string]string{"status":"ready"})});mux.HandleFunc("POST /ask",func(w http.ResponseWriter,r *http.Request){if c.Token!=""{got:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer ");if subtle.ConstantTimeCompare([]byte(got),[]byte(c.Token))!=1{write(w,401,map[string]string{"error":"bearer token required"});return}};r.Body=http.MaxBytesReader(w,r.Body,64<<10);var q struct{Question string `json:"question"`};d:=json.NewDecoder(r.Body);d.DisallowUnknownFields();if d.Decode(&q)!=nil{write(w,400,map[string]string{"error":"invalid JSON body"});return};ctx,cancel:=time.WithTimeout(r.Context(),90*time.Second);defer cancel();start:=time.Now();result,err:=e.Ask(ctx,q.Question);if err!=nil{log.Printf("inference error: %v",err);write(w,502,map[string]string{"error":"retrieval pipeline failed"});return};log.Printf("inference completed in %s verdict=%s",time.Since(start),result.Verdict);write(w,200,result)})
return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("Cache-Control","no-store");origin:=r.Header.Get("Origin");for _,allowed:=range strings.Split(c.Origins,","){if origin!=""&&origin==strings.TrimSpace(allowed){w.Header().Set("Access-Control-Allow-Origin",origin);w.Header().Set("Vary","Origin");w.Header().Set("Access-Control-Allow-Headers","Authorization, Content-Type");w.Header().Set("Access-Control-Allow-Methods","GET, POST, OPTIONS")}};if r.Method=="OPTIONS"{w.WriteHeader(204);return};mux.ServeHTTP(w,r)})}
func write(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
